import React from 'react';
import { Link as RouterLink } from 'react-router-dom';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  LinearProgress,
  Link,
  Stack,
  Typography,
} from '@mui/material';

export interface DataQualityReadiness {
  threshold?: number;
  confidence?: number;
  passed?: boolean;
  effect?: string;
  relationToEmissions?: string;
}

const formatConfidence = (value?: number) => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 'n/a';
  }
  return `${Math.round(numeric * 100)}%`;
};

export const DataQualityReadinessCard: React.FC<{
  readiness?: DataQualityReadiness | null;
  title?: string;
  simplified?: boolean;
}> = ({ readiness, title = 'Data quality readiness', simplified = false }) => {
  if (!readiness) {
    return null;
  }

  const threshold = Number.isFinite(Number(readiness.threshold))
    ? Number(readiness.threshold)
    : 0.65;
  const confidence = Number.isFinite(Number(readiness.confidence))
    ? Number(readiness.confidence)
    : 0;
  const passed = readiness.passed ?? confidence >= threshold;
  const progressValue = Math.min(100, Math.max(0, confidence * 100));
  const cardTitle = simplified ? 'Bill & data confidence' : title;
  const thresholdLabel = simplified ? 'Target' : 'Threshold';

  return (
    <Card variant="outlined">
      <CardContent>
        <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
          <Typography variant="subtitle1">{cardTitle}</Typography>
          <Chip
            size="small"
            label={passed ? (simplified ? 'Good enough' : 'Meets threshold') : (simplified ? 'Needs more bills' : 'Below threshold')}
            color={passed ? 'success' : 'warning'}
            variant="outlined"
          />
        </Stack>

        <Stack direction="row" alignItems="center" spacing={2} sx={{ mb: 1 }}>
          <Typography variant="h5">{formatConfidence(confidence)}</Typography>
          <Box sx={{ flex: 1 }}>
            <LinearProgress
              variant="determinate"
              value={progressValue}
              color={passed ? 'success' : 'warning'}
              sx={{ height: 8, borderRadius: 1 }}
            />
          </Box>
          <Typography variant="caption" color="text.secondary">
            {thresholdLabel} {formatConfidence(threshold)}
          </Typography>
        </Stack>

        {!passed && (
          <Alert severity="warning" sx={{ mb: 1 }}>
            {simplified
              ? 'Upload a few more utility or fuel bills to unlock filing-ready exports. Your emissions numbers are still calculated.'
              : (readiness.effect
                || 'Filing-ready ISO 14064 export is blocked until confidence reaches the threshold. Emissions calculations are not rejected.')}
          </Alert>
        )}

        {!passed && (
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mb: 1.5 }} flexWrap="wrap" useFlexGap alignItems="center">
            <Button
              size="small"
              variant="contained"
              component={RouterLink}
              to="/document-upload"
            >
              Upload bills
            </Button>
            <Button
              size="small"
              variant="outlined"
              component={RouterLink}
              to="/data?section=connectors"
            >
              {simplified ? 'Connect accounting' : 'Sync accounting data'}
            </Button>
            {simplified ? (
              <Link component={RouterLink} to="/compliance/india?section=iso-assurance" variant="caption">
                What does this score mean?
              </Link>
            ) : (
              <Button
                size="small"
                variant="outlined"
                component={RouterLink}
                to="/compliance/india?section=iso-assurance"
              >
                Open ISO hub
              </Button>
            )}
          </Stack>
        )}

        {passed && readiness.effect && (
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            {readiness.effect}
          </Typography>
        )}

        <Typography variant="caption" color="text.secondary" display="block">
          {simplified
            ? 'This score reflects how complete your bill and transaction data is — it does not change your kg CO₂e totals.'
            : (readiness.relationToEmissions
              || 'Data quality confidence is readiness metadata — it does not multiply or alter kg CO₂e calculations.')}
        </Typography>
      </CardContent>
    </Card>
  );
};
